import{_ as a}from"./chunks/position_fixed.t2m3lWVy.js";import{_ as s}from"./chunks/rover_control_structure.ClmRSlLB.js";import{_ as n,C as d,o as l,c,al as r,j as e,a as o,E as h}from"./chunks/framework.7vp1BMOE.js";const k=JSON.parse('{"title":"Offboard Mode (Generic/All Frames)","description":"","frontmatter":{},"headers":[],"relativePath":"uk/flight_modes/offboard.md","filePath":"uk/flight_modes/offboard.md"}'),p={name:"uk/flight_modes/offboard.md"},f={tabindex:"0"};function m(u,t,_,g,b,v){const i=d("Badge");return l(),c("div",null,[t[8]||(t[8]=r('<h1 id="offboard-mode-generic-all-frames" tabindex="-1">Offboard Mode (Generic/All Frames) <a class="header-anchor" href="#offboard-mode-generic-all-frames" aria-label="Permalink to &quot;Offboard Mode (Generic/All Frames)&quot;">​</a></h1><img src="'+a+`" title="Position fix required (e.g. GPS)" width="30px"><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Offboard control with ROS 2 requires <em>significant care</em> to ensure that it is used safely. Please read <a href="#ros-2-offboard-control">ROS 2 Offboard Control</a> carefully to fully understand the risks involved when using it. A good understanding of <a href="./../flight_stack/controller_diagrams">PX4 controller diagrams</a> is advised.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><a href="./../ros2/px4_ros2_interface_lib">PX4 ROS 2 Interface Library</a> provides a safer alternative.</p></div></div><p>Апарат зберігає данні про положення, швидкість, прискорення, орієнтацію, значення сили тяги, відповідно заданим значенням, наданим деяким джерелом, зовнішнім по відношенню до польотного контролера, наприклад комп’ютером. The setpoints may be provided using MAVLink (or a MAVLink API such as <a href="https://mavsdk.mavlink.io/" target="_blank" rel="noreferrer">MAVSDK</a>) or by <a href="./../ros2/">ROS 2</a>.</p><h2 id="технічнии-підсумок" tabindex="-1">Технічний підсумок <a class="header-anchor" href="#технічнии-підсумок" aria-label="Permalink to &quot;Технічний підсумок&quot;">​</a></h2><p>PX4 requires that the external controller provides a continuous 2Hz &quot;proof of life&quot; signal, by streaming any of the supported MAVLink setpoint messages or the ROS 2 <a href="./../msg_docs/OffboardControlMode">OffboardControlMode</a> message. The stream should be active before switching to Offboard mode, and PX4 will trigger the configured Offboard-loss failsafe action (<a href="./../advanced_config/parameter_reference#COM_OBL_RC_ACT">COM_OBL_RC_ACT</a>) if proof-of-life messages are not received within the timeout configured by <a href="#COM_OF_LOSS_T">COM_OF_LOSS_T</a>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><ul><li>This mode requires position or pose/attitude information - e.g. GPS, optical flow, visual-inertial odometry, mocap, etc. depending on the type of offboard setpoints that the external controller sends.</li><li>Manual control is disabled except to change modes (you can also fly without any manual controller at all by setting the parameter <a href="./../advanced_config/parameter_reference#COM_RC_IN_MODE">COM_RC_IN_MODE</a> to <code>4: Disable manual control</code>).</li><li>The vehicle must already be receiving a stream of MAVLink setpoint messages or ROS 2 <a href="./../msg_docs/OffboardControlMode">OffboardControlMode</a> messages before arming in offboard mode or switching to offboard mode when flying.</li><li>The vehicle will exit Offboard mode if MAVLink setpoint messages or <code>OffboardControlMode</code> messages stop being received for longer than the timeout configured by <a href="#COM_OF_LOSS_T">COM_OF_LOSS_T</a>.</li><li>Не всі значення координат та параметрів, дозволені MAVLink підтримуються для усіх повідомлень та транспортних засобів. Read the sections below <em>carefully</em> to ensure only supported values are used.</li></ul></div><h3 id="mode-requirements-—-fixed-wing" tabindex="-1">Mode Requirements — Fixed-Wing <a class="header-anchor" href="#mode-requirements-—-fixed-wing" aria-label="Permalink to &quot;Mode Requirements — Fixed-Wing&quot;">​</a></h3><p>The following requirements must be met to arm in this mode, or to switch to this mode when it is armed.</p><ul><li><a href="./../flight_modes/mode_requirements#mode_req_angular_velocity"><code>mode_req_angular_velocity</code></a> — Angular velocity</li><li><a href="./../flight_modes/mode_requirements#mode_req_attitude"><code>mode_req_attitude</code></a> — Attitude/pose</li><li><a href="./../flight_modes/mode_requirements#mode_req_offboard_signal"><code>mode_req_offboard_signal</code></a> — Offboard heartbeat</li></ul><h3 id="mode-requirements-—-multicopter" tabindex="-1">Mode Requirements — Multicopter <a class="header-anchor" href="#mode-requirements-—-multicopter" aria-label="Permalink to &quot;Mode Requirements — Multicopter&quot;">​</a></h3><p>The following requirements must be met to arm in this mode, or to switch to this mode when it is armed.</p><ul><li><a href="./../flight_modes/mode_requirements#mode_req_angular_velocity"><code>mode_req_angular_velocity</code></a> — Angular velocity</li><li><a href="./../flight_modes/mode_requirements#mode_req_attitude"><code>mode_req_attitude</code></a> — Attitude/pose</li><li><a href="./../flight_modes/mode_requirements#mode_req_offboard_signal"><code>mode_req_offboard_signal</code></a> — Offboard heartbeat</li></ul><h2 id="опис" tabindex="-1">Опис <a class="header-anchor" href="#опис" aria-label="Permalink to &quot;Опис&quot;">​</a></h2><p>Offboard mode is used for controlling vehicle movement and attitude, by setting position, velocity, acceleration, attitude, attitude rates or thrust/torque setpoints. PX4 must receive a stream of MAVLink setpoint messages or the ROS 2 <a href="./../msg_docs/OffboardControlMode">OffboardControlMode</a> message as proof that the external controller is healthy. The stream should be active before PX4 arms in Offboard mode or switches to Offboard mode when flying. If MAVLink setpoint messages or <code>OffboardControlMode</code> messages stop being received for longer than the timeout configured by <a href="#COM_OF_LOSS_T">COM_OF_LOSS_T</a>, PX4 will switch out of Offboard mode and attempt to land or perform some other failsafe action. The action depends on whether or not RC control is available, and is defined in the parameter <a href="#COM_OBL_RC_ACT">COM_OBL_RC_ACT</a>.</p><p>When using MAVLink the setpoint messages convey both the signal to indicate that the external source is &quot;alive&quot;, and the setpoint value itself. In order to hold position in this case the vehicle must receive a stream of setpoints for the current position.</p><p>When using ROS 2 the proof that the external source is alive is provided by a stream of <a href="./../msg_docs/OffboardControlMode">OffboardControlMode</a> messages, while the actual setpoint is provided by publishing to one of the setpoint uORB topics, such as <a href="./../msg_docs/TrajectorySetpoint">TrajectorySetpoint</a>. In order to hold position in this case the vehicle must receive a stream of <code>OffboardControlMode</code> but would only need the <code>TrajectorySetpoint</code> once.</p><p>Note that offboard mode only supports a very limited set of MAVLink commands and messages. Operations, like taking off, landing, return to launch, may be best handled using the appropriate modes. Operations like uploading, downloading missions can be performed in any mode.</p><h2 id="ros-2-offboard-control" tabindex="-1">ROS 2 Offboard Control <a class="header-anchor" href="#ros-2-offboard-control" aria-label="Permalink to &quot;ROS 2 Offboard Control&quot;">​</a></h2><p>This section describes how to perform offboard control through one of the direct ROS 2 interfaces: UXRCE-DDS or Zenoh.</p><p>When using direct ROS 2 offboard control, PX4 setpoint messages generated by external controllers are injected into the <a href="./../flight_stack/controller_diagrams">PX4 control pipeline</a>. Because messages from internal and external controllers are indistinguishable within PX4, precise synchronization is required in order to avoid the controllers writing conflicting messages to the same topic.</p><p>In Offboard mode (only), an external system can use <a href="#the-offboardcontrolmode-px4-message"><code>OffboardControlMode</code></a> to specify which setpoint topics PX4 should publish/not publish, allowing them to be written safely by an external controller.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 has no means of filtering and distinguishing ROS 2 messages from internal messages, in any mode. In order to interwork safely, the external controller must:</p><ul><li>Publish PX4 setpoint messages <strong>ONLY</strong> in Offboard mode.</li><li>Specify which setpoints it will write using the <code>OffboardControlMode</code> topic.</li><li>Stream the <code>OffboardControlMode</code> topic as a keep-alive signal.</li><li>Stream the setpoints it wants: unlike with MAVLink, PX4 won&#39;t trigger a failsafe if setpoints aren&#39;t sent regularly.</li></ul><p>If external setpoints are sent in any other flight mode, or they overwrite topics that have not been disabled by PX4 when in offboard mode, collisions are likely. This will result in unexpected, and possibly catastrophic, behaviour.</p></div><h3 id="the-offboardcontrolmode-px4-message" tabindex="-1">The <code>OffboardControlMode</code> PX4 message <a class="header-anchor" href="#the-offboardcontrolmode-px4-message" aria-label="Permalink to &quot;The \`OffboardControlMode\` PX4 message&quot;">​</a></h3><p>The following ROS 2 messages and their particular fields and field values are allowed for the specified frames. In addition to providing heartbeat functionality, <code>OffboardControlMode</code> has two other main purposes:</p><ol><li>Controls which internal PX4 control modules of the <a href="./../flight_stack/controller_diagrams">PX4 control architecture</a> shall remain active and which ones shall be disabled when the vehicle is in Offboard Mode.</li><li>Determines which valid estimates (position, velocity, etc.) are required.</li></ol><p>The <code>OffboardControlMode</code> message is defined as shown.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Off-board control mode</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uint64</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> timestamp</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">		# time since system start (microseconds)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bool</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> position</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bool</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> velocity</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bool</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> acceleration</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bool</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> attitude</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bool</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> body_rate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bool</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> thrust_and_torque</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bool</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> direct_actuator</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The following list shows the <code>OffboardControlMode</code> options for copter, fixed-wing, and VTOL. For rovers see the <a href="#rover">rover section</a>.</p></div><p>The fields are ordered in terms of priority such that <code>position</code> takes precedence over <code>velocity</code> and later fields, <code>velocity</code> takes precedence over <code>acceleration</code>, and so on. The first field that has a non-zero value (from top to bottom) defines what valid estimate is required in order to use offboard mode, and the setpoint message(s) that can be used. For example, if the <code>acceleration</code> field is the first non-zero value, then PX4 requires a valid <code>attitude estimate</code>, and the setpoint must be specified using the <code>TrajectorySetpoint</code> message.</p><table tabindex="0"><thead><tr><th>desired control quantity</th><th>position field</th><th>velocity field</th><th>acceleration field</th><th>attitude field</th><th>body_rate field</th><th>thrust_and_torque field</th><th>direct_actuator field</th><th>required estimate</th><th>required message</th></tr></thead><tbody><tr><td>position (NED)</td><td>✓</td><td>-</td><td>-</td><td>-</td><td>-</td><td>-</td><td>-</td><td>position</td><td><a href="./../msg_docs/TrajectorySetpoint">TrajectorySetpoint</a></td></tr><tr><td>velocity (NED)</td><td>✗</td><td>✓</td><td>-</td><td>-</td><td>-</td><td>-</td><td>-</td><td>velocity</td><td><a href="./../msg_docs/TrajectorySetpoint">TrajectorySetpoint</a></td></tr><tr><td>acceleration (NED)</td><td>✗</td><td>✗</td><td>✓</td><td>-</td><td>-</td><td>-</td><td>-</td><td>attitude</td><td><a href="./../msg_docs/TrajectorySetpoint">TrajectorySetpoint</a></td></tr><tr><td>attitude (FRD)</td><td>✗</td><td>✗</td><td>✗</td><td>✓</td><td>-</td><td>-</td><td>-</td><td>attitude</td><td><a href="./../msg_docs/VehicleAttitudeSetpoint">VehicleAttitudeSetpoint</a></td></tr><tr><td>body_rate (FRD)</td><td>✗</td><td>✗</td><td>✗</td><td>✗</td><td>✓</td><td>-</td><td>-</td><td>angular velocity</td><td><a href="./../msg_docs/VehicleRatesSetpoint">VehicleRatesSetpoint</a></td></tr><tr><td>thrust and torque (FRD)</td><td>✗</td><td>✗</td><td>✗</td><td>✗</td><td>✗</td><td>✓</td><td>-</td><td>none</td><td><a href="./../msg_docs/VehicleThrustSetpoint">VehicleThrustSetpoint</a> and <a href="./../msg_docs/VehicleTorqueSetpoint">VehicleTorqueSetpoint</a></td></tr><tr><td>direct motors and servos</td><td>✗</td><td>✗</td><td>✗</td><td>✗</td><td>✗</td><td>✗</td><td>✓</td><td>none</td><td><a href="./../msg_docs/ActuatorMotors">ActuatorMotors</a> and <a href="./../msg_docs/ActuatorServos">ActuatorServos</a></td></tr></tbody></table><p>where ✓ means that the bit is set, ✘ means that the bit is not set and <code>-</code> means that the bit value is irrelevant.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Before using offboard mode with ROS 2, please spend a few minutes understanding the different <a href="./../ros2/user_guide#ros-2-px4-frame-conventions">frame conventions</a> that PX4 and ROS 2 use.</p></div><p>In the following, the different setpoint messages for the main supported airframes are explained. For fixed-wing offboard control, please refer to the <a href="./../ros2/px4_ros2_interface_lib">PX4 ROS 2 Interface Library</a>.</p><h3 id="мультикоптери" tabindex="-1">Мультикоптери <a class="header-anchor" href="#мультикоптери" aria-label="Permalink to &quot;Мультикоптери&quot;">​</a></h3><ul><li><p><a href="https://github.com/PX4/PX4-Autopilot/blob/main/msg/versioned/TrajectorySetpoint.msg" target="_blank" rel="noreferrer">px4_msgs::msg::TrajectorySetpoint</a></p><ul><li><p>The following input combinations are supported:</p><ul><li>Position setpoint (<code>position</code> different from <code>NaN</code>). Non-<code>NaN</code> values of velocity and acceleration are used as feedforward terms for the inner loop controllers.</li><li>Velocity setpoint (<code>velocity</code> different from <code>NaN</code> and <code>position</code> set to <code>NaN</code>). Non-<code>NaN</code> values of acceleration are used as feedforward terms for the inner loop controllers.</li><li>Acceleration setpoint (<code>acceleration</code> different from <code>NaN</code> and <code>position</code> and <code>velocity</code> set to <code>NaN</code>)</li></ul></li><li><p>All values are interpreted in NED (North, East, Down) coordinate system and the units are <code>[m]</code>, <code>[m/s]</code> and <code>[m/s^2]</code> for position, velocity and acceleration, respectively.</p></li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Position, velocity and acceleration control for multicopters are all handled by the <code>mc_pos_control</code> module. This module is enabled if any of <code>position</code>, <code>velocity</code> and <code>acceleration</code> fields are set to true. However, only the content of the <code>TrajectorySetpoint</code> messages determines which of the three controllers shall run.</p><p>This means that even if <code>OffboardControlMode</code> messages carry the intention of velocity control (only <code>velocity</code> field is set) but non-<code>NaN</code> position values are sent in the <code>TrajectorySetpoint</code> messages, then PX4 will keep running the position controller.</p></div></li></ul><p>:::</p><ul><li><p><a href="https://github.com/PX4/PX4-Autopilot/blob/main/msg/versioned/VehicleAttitudeSetpoint.msg" target="_blank" rel="noreferrer">px4_msgs::msg::VehicleAttitudeSetpoint</a></p><ul><li><p>The following input combination is supported:</p><ul><li>quaternion <code>q_d</code> + thrust setpoint <code>thrust_body</code>. Non-<code>NaN</code> values of <code>yaw_sp_move_rate</code> are used as feedforward terms expressed in Earth frame and in <code>[rad/s]</code>.</li></ul></li><li><p>The quaternion represents the rotation between the drone body FRD (front, right, down) frame and the NED frame. The thrust is in the drone body FRD frame and expressed in normalized [-1, 1] values.</p></li></ul></li><li><p><a href="https://github.com/PX4/PX4-Autopilot/blob/main/msg/versioned/VehicleRatesSetpoint.msg" target="_blank" rel="noreferrer">px4_msgs::msg::VehicleRatesSetpoint</a></p><ul><li><p>The following input combination is supported:</p><ul><li><code>roll</code>, <code>pitch</code>, <code>yaw</code> and <code>thrust_body</code>.</li></ul></li><li><p>All the values are in the drone body FRD frame. The rates are in <code>[rad/s]</code> while thrust_body is normalized in <code>[-1, 1]</code>.</p></li></ul></li></ul><h3 id="rover" tabindex="-1">Rover <a class="header-anchor" href="#rover" aria-label="Permalink to &quot;Rover&quot;">​</a></h3><p>Rover modules must set the control mode using <code>OffboardControlMode</code> and use the appropriate messages to configure the corresponding setpoints. The approach is similar to other vehicle types, but the allowed control mode combinations and setpoints are different:</p><table tabindex="0"><thead><tr><th>Category</th><th>Використання</th><th>Setpoints</th></tr></thead><tbody><tr><td>(Recommended) <a href="#rover-setpoints">Rover Setpoints</a></td><td>General rover control</td><td><a href="./../msg_docs/RoverPositionSetpoint">RoverPositionSetpoint</a>, <a href="./../msg_docs/RoverSpeedSetpoint">RoverSpeedSetpoint</a>, <a href="./../msg_docs/RoverAttitudeSetpoint">RoverAttitudeSetpoint</a>, <a href="./../msg_docs/RoverRateSetpoint">RoverRateSetpoint</a>, <a href="./../msg_docs/RoverThrottleSetpoint">RoverThrottleSetpoint</a>, <a href="./../msg_docs/RoverSteeringSetpoint">RoverSteeringSetpoint</a></td></tr><tr><td><a href="#actuator-setpoints">Actuator Setpoints</a></td><td>Direct actuator control</td><td><a href="./../msg_docs/ActuatorMotors">ActuatorMotors</a>, <a href="./../msg_docs/ActuatorServos">ActuatorServos</a></td></tr><tr><td>(Deprecated) <a href="#deprecated-trajectory-setpoint">Trajectory Setpoint</a></td><td>General vehicle control</td><td><a href="./../msg_docs/TrajectorySetpoint">TrajectorySetpoint</a></td></tr></tbody></table><h4 id="rover-setpoints" tabindex="-1">Rover Setpoints <a class="header-anchor" href="#rover-setpoints" aria-label="Permalink to &quot;Rover Setpoints&quot;">​</a></h4><p>The rover modules use a hierarchical structure to propagate setpoints:</p><p><img src="`+s+`" alt="Rover Control Structure"></p><p>The &quot;highest&quot; setpoint that is provided will be used within the PX4 rover modules to generate the setpoints that are below it (overriding them!). With this hierarchy there are clear rules for providing a valid control input:</p><ul><li>Provide a position setpoint <strong>or</strong></li><li>One of the setpoints on the &quot;left&quot; (speed <strong>or</strong> throttle) <strong>and</strong> one of the setpoints on the &quot;right&quot; (attitude, rate <strong>or</strong> steering). All combinations of &quot;left&quot; and &quot;right&quot; setpoints are valid.</li></ul><p>The following are all valid setpoint combinations and their respective control flags that must be set through <a href="./../msg_docs/OffboardControlMode">OffboardControlMode</a> (set all others to <em>false</em>). Additionally, for some combinations we require certain setpoints to be published with <code>NAN</code> values so that the setpoints of interest are not overridden by the rover module (due to the hierarchy above). ✓ are the relevant setpoints we publish, and ✗ are the setpoint that need to be published with <code>NAN</code> values.</p><table tabindex="0"><thead><tr><th>Setpoint Combination</th><th>Control Flag</th><th><a href="./../msg_docs/RoverPositionSetpoint">RoverPositionSetpoint</a></th><th><a href="./../msg_docs/RoverSpeedSetpoint">RoverSpeedSetpoint</a></th><th><a href="./../msg_docs/RoverThrottleSetpoint">RoverThrottleSetpoint</a></th><th><a href="./../msg_docs/RoverAttitudeSetpoint">RoverAttitudeSetpoint</a></th><th><a href="./../msg_docs/RoverRateSetpoint">RoverRateSetpoint</a></th><th><a href="./../msg_docs/RoverSteeringSetpoint">RoverSteeringSetpoint</a></th></tr></thead><tbody><tr><td>Положення</td><td>position</td><td>✓</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Speed + Attitude</td><td>velocity</td><td></td><td>✓</td><td></td><td>✓</td><td></td><td></td></tr><tr><td>Speed + Rate</td><td>velocity</td><td></td><td>✓</td><td></td><td>✗</td><td>✓</td><td></td></tr><tr><td>Speed + Steering</td><td>velocity</td><td></td><td>✓</td><td></td><td>✗</td><td>✗</td><td>✓</td></tr><tr><td>Throttle + Attitude</td><td>attitude</td><td></td><td></td><td>✓</td><td>✓</td><td></td><td></td></tr><tr><td>Throttle + Rate</td><td>body_rate</td><td></td><td></td><td>✓</td><td></td><td>✓</td><td></td></tr><tr><td>Throttle + Steering</td><td>thrust_and_torque</td><td></td><td></td><td>✓</td><td></td><td></td><td>✓</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If you intend to use the rover setpoints, we recommend using the <a href="./../ros2/px4_ros2_interface_lib">PX4 ROS 2 Interface Library</a> instead since it simplifies the publishing of these setpoints.</p></div><h4 id="actuator-setpoints" tabindex="-1">Actuator Setpoints <a class="header-anchor" href="#actuator-setpoints" aria-label="Permalink to &quot;Actuator Setpoints&quot;">​</a></h4><p>Instead of controlling the vehicle using position, speed, rate and other setpoints, you can directly control the motors and actuators using <a href="./../msg_docs/ActuatorMotors">ActuatorMotors</a> and <a href="./../msg_docs/ActuatorServos">ActuatorServos</a>. In <a href="./../msg_docs/OffboardControlMode">OffboardControlMode</a> set <code>direct_actuator</code> to <em>true</em> and all other flags to <em>false</em>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This bypasses the rover modules including any limits on steering rates or accelerations and the inverse kinematics step. We recommend using <a href="./../msg_docs/RoverSteeringSetpoint">RoverSteeringSetpoint</a> and <a href="./../msg_docs/RoverThrottleSetpoint">RoverThrottleSetpoint</a> instead for low level control (see <a href="#rover-setpoints">Rover Setpoints</a>).</p></div><h4 id="deprecated-trajectory-setpoint" tabindex="-1">(Deprecated) Trajectory Setpoint <a class="header-anchor" href="#deprecated-trajectory-setpoint" aria-label="Permalink to &quot;(Deprecated) Trajectory Setpoint&quot;">​</a></h4><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The <a href="#rover-setpoints">Rover Setpoints</a> are a replacement for the <a href="./../msg_docs/TrajectorySetpoint">TrajectorySetpoint</a> and we highly recommend using those instead as they have a well defined behaviour and offer more flexibility.</p></div><p>The rover modules support the <em>position</em>, <em>velocity</em> and <em>yaw</em> fields of the <a href="./../msg_docs/TrajectorySetpoint">TrajectorySetpoint</a>. However, only one of the fields is active at a time and is defined by the flags of <a href="./../msg_docs/OffboardControlMode">OffboardControlMode</a>:</p><table tabindex="0"><thead><tr><th>Control Mode Flag</th><th>Active Trajectory Setpoint Field</th></tr></thead><tbody><tr><td>position</td><td>position</td></tr><tr><td>velocity</td><td>velocity</td></tr><tr><td>attitude</td><td>yaw</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Ackermann rovers do not support the yaw setpoint.</p></div><h3 id="generic-vehicle" tabindex="-1">Generic Vehicle <a class="header-anchor" href="#generic-vehicle" aria-label="Permalink to &quot;Generic Vehicle&quot;">​</a></h3><p>The following offboard control modes bypass all internal PX4 control loops and should be used with great care.</p><ul><li><p><a href="https://github.com/PX4/PX4-Autopilot/blob/main/msg/VehicleThrustSetpoint.msg" target="_blank" rel="noreferrer">px4_msgs::msg::VehicleThrustSetpoint</a> + <a href="https://github.com/PX4/PX4-Autopilot/blob/main/msg/VehicleTorqueSetpoint.msg" target="_blank" rel="noreferrer">px4_msgs::msg::VehicleTorqueSetpoint</a></p><ul><li>The following input combination is supported: <ul><li><code>xyz</code> for thrust and <code>xyz</code> for torque.</li></ul></li><li>All the values are in the drone body FRD frame and normalized in [-1, 1].</li></ul></li><li><p><a href="https://github.com/PX4/PX4-Autopilot/blob/main/msg/versioned/ActuatorMotors.msg" target="_blank" rel="noreferrer">px4_msgs::msg::ActuatorMotors</a> + <a href="https://github.com/PX4/PX4-Autopilot/blob/main/msg/versioned/ActuatorServos.msg" target="_blank" rel="noreferrer">px4_msgs::msg::ActuatorServos</a></p><ul><li>You directly control the motor outputs and/or servo outputs.</li><li>All the values normalized in <code>[-1, 1]</code>. For outputs that do not support negative values, negative entries map to <code>NaN</code>.</li><li><code>NaN</code> maps to disarmed.</li></ul></li></ul><h2 id="mavlink-offboard-control" tabindex="-1">MAVLink Offboard Control <a class="header-anchor" href="#mavlink-offboard-control" aria-label="Permalink to &quot;MAVLink Offboard Control&quot;">​</a></h2><p>The following MAVLink messages and their particular fields and field values are allowed for the specified vehicle frames.</p><h3 id="copter-vtol" tabindex="-1">Copter/VTOL <a class="header-anchor" href="#copter-vtol" aria-label="Permalink to &quot;Copter/VTOL&quot;">​</a></h3><ul><li><p><a href="https://mavlink.io/en/messages/common.html#SET_POSITION_TARGET_LOCAL_NED" target="_blank" rel="noreferrer">SET_POSITION_TARGET_LOCAL_NED</a></p><ul><li><p>The following input combinations are supported: </p><ul><li>Position setpoint (only <code>x</code>, <code>y</code>, <code>z</code>)</li><li>Velocity setpoint (only <code>vx</code>, <code>vy</code>, <code>vz</code>)</li><li>Acceleration setpoint (only <code>afx</code>, <code>afy</code>, <code>afz</code>)</li><li>Position setpoint <strong>and</strong> velocity setpoint (the velocity setpoint is used as feedforward; it is added to the output of the position controller and the result is used as the input to the velocity controller).</li><li>Position setpoint <strong>and</strong> velocity setpoint <strong>and</strong> acceleration (the velocity and the acceleration setpoints are used as feedforwards; the velocity setpoint is added to the output of the position controller and the result is used as the input to the velocity controller; the acceleration setpoint is added to the output of the velocity controller and the result used to compute the thrust vector).</li></ul></li><li><p>PX4 supports the following <code>coordinate_frame</code> values (only): <a href="https://mavlink.io/en/messages/common.html#MAV_FRAME_LOCAL_NED" target="_blank" rel="noreferrer">MAV_FRAME_LOCAL_NED</a> and <a href="https://mavlink.io/en/messages/common.html#MAV_FRAME_BODY_NED" target="_blank" rel="noreferrer">MAV_FRAME_BODY_NED</a>.</p></li></ul></li><li><p><a href="https://mavlink.io/en/messages/common.html#SET_POSITION_TARGET_GLOBAL_INT" target="_blank" rel="noreferrer">SET_POSITION_TARGET_GLOBAL_INT</a></p><ul><li>The following input combinations are supported: <ul><li><p>Position setpoint (only <code>lat_int</code>, <code>lon_int</code>, <code>alt</code>)</p></li><li><p>Velocity setpoint (only <code>vx</code>, <code>vy</code>, <code>vz</code>)</p></li><li><p><em>Thrust</em> setpoint (only <code>afx</code>, <code>afy</code>, <code>afz</code>)</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Acceleration setpoint values are mapped to create a normalized thrust setpoint (i.e. acceleration setpoints are not &quot;properly&quot; supported).</p></div></li></ul></li></ul></li></ul><p>:::</p><pre><code>- Position setpoint **and** velocity setpoint (the velocity setpoint is used as feedforward; it is added to the output of the position controller and the result is used as the input to the velocity controller).
</code></pre><ul><li><p>PX4 supports the following <code>coordinate_frame</code> values (only): <a href="https://mavlink.io/en/messages/common.html#MAV_FRAME_GLOBAL_INT" target="_blank" rel="noreferrer">MAV_FRAME_GLOBAL_INT</a>, <a href="https://mavlink.io/en/messages/common.html#MAV_FRAME_GLOBAL_RELATIVE_ALT_INT" target="_blank" rel="noreferrer">MAV_FRAME_GLOBAL_RELATIVE_ALT_INT</a>, <a href="https://mavlink.io/en/messages/common.html#MAV_FRAME_GLOBAL_TERRAIN_ALT_INT" target="_blank" rel="noreferrer">MAV_FRAME_GLOBAL_TERRAIN_ALT_INT</a>.</p></li><li><p><a href="https://mavlink.io/en/messages/common.html#SET_ATTITUDE_TARGET" target="_blank" rel="noreferrer">SET_ATTITUDE_TARGET</a></p><ul><li>The following input combinations are supported: <ul><li>Attitude/orientation (<code>SET_ATTITUDE_TARGET.q</code>) with thrust setpoint (<code>SET_ATTITUDE_TARGET.thrust</code>).</li><li>Body rate (<code>SET_ATTITUDE_TARGET</code> <code>.body_roll_rate</code> ,<code>.body_pitch_rate</code>, <code>.body_yaw_rate</code>) with thrust setpoint (<code>SET_ATTITUDE_TARGET.thrust</code>).</li></ul></li></ul></li></ul><h3 id="fixed-wing" tabindex="-1">Fixed-wing <a class="header-anchor" href="#fixed-wing" aria-label="Permalink to &quot;Fixed-wing&quot;">​</a></h3><ul><li><a href="https://mavlink.io/en/messages/common.html#SET_POSITION_TARGET_LOCAL_NED" target="_blank" rel="noreferrer">SET_POSITION_TARGET_LOCAL_NED</a><ul><li>The following input combinations are supported (via <code>type_mask</code>): <ul><li>Position setpoint (<code>x</code>, <code>y</code>, <code>z</code> only; velocity and acceleration setpoints are ignored). <ul><li>Specify the <em>type</em> of the setpoint in <code>type_mask</code> (if these bits are not set the vehicle will fly in a flower-like pattern):<div class="info custom-block"><p class="custom-block-title">INFO</p><p>Some of the <em>setpoint type</em> values below are not part of the MAVLink standard for the <code>type_mask</code> field.</p></div></li></ul></li></ul></li></ul></li></ul><p>:::</p><pre><code>    The values are:

    - 292: Gliding setpoint.
      This configures TECS to prioritize airspeed over altitude in order to make the vehicle glide when there is no thrust (i.e. pitch is controlled to regulate airspeed).
      It is equivalent to setting \`type_mask\` as \`POSITION_TARGET_TYPEMASK_Z_IGNORE\`, \`POSITION_TARGET_TYPEMASK_VZ_IGNORE\`, \`POSITION_TARGET_TYPEMASK_AZ_IGNORE\`.
    - 4096: Takeoff setpoint.
    - 8192: Land setpoint.
    - 12288: Loiter setpoint (fly a circle centred on setpoint).
    - 16384: Idle setpoint (zero throttle, zero roll / pitch).
</code></pre><ul><li><p>PX4 supports the coordinate frames (<code>coordinate_frame</code> field): <a href="https://mavlink.io/en/messages/common.html#MAV_FRAME_LOCAL_NED" target="_blank" rel="noreferrer">MAV_FRAME_LOCAL_NED</a> and <a href="https://mavlink.io/en/messages/common.html#MAV_FRAME_BODY_NED" target="_blank" rel="noreferrer">MAV_FRAME_BODY_NED</a>.</p></li><li><p><a href="https://mavlink.io/en/messages/common.html#SET_POSITION_TARGET_GLOBAL_INT" target="_blank" rel="noreferrer">SET_POSITION_TARGET_GLOBAL_INT</a></p><ul><li>The following input combinations are supported (via <code>type_mask</code>): <ul><li>Position setpoint (only <code>lat_int</code>, <code>lon_int</code>, <code>alt</code>) <ul><li><p>Specify the <em>type</em> of the setpoint in <code>type_mask</code> (if these bits are not set the vehicle will fly in a flower-like pattern):</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The <em>setpoint type</em> values below are not part of the MAVLink standard for the <code>type_mask</code> field.</p></div></li></ul></li></ul></li></ul></li></ul><p>:::</p><pre><code>    The values are:

    - 4096: Takeoff setpoint.
    - 8192: Land setpoint.
    - 12288: Loiter setpoint (fly a circle centred on setpoint).
    - 16384: Idle setpoint (zero throttle, zero roll / pitch).
</code></pre><ul><li><p>PX4 supports the following <code>coordinate_frame</code> values (only): <a href="https://mavlink.io/en/messages/common.html#MAV_FRAME_GLOBAL_INT" target="_blank" rel="noreferrer">MAV_FRAME_GLOBAL_INT</a>, <a href="https://mavlink.io/en/messages/common.html#MAV_FRAME_GLOBAL_RELATIVE_ALT_INT" target="_blank" rel="noreferrer">MAV_FRAME_GLOBAL_RELATIVE_ALT_INT</a>, <a href="https://mavlink.io/en/messages/common.html#MAV_FRAME_GLOBAL_TERRAIN_ALT_INT" target="_blank" rel="noreferrer">MAV_FRAME_GLOBAL_TERRAIN_ALT_INT</a>.</p></li><li><p><a href="https://mavlink.io/en/messages/common.html#SET_ATTITUDE_TARGET" target="_blank" rel="noreferrer">SET_ATTITUDE_TARGET</a></p><ul><li>The following input combinations are supported: <ul><li>Attitude/orientation (<code>SET_ATTITUDE_TARGET.q</code>) with thrust setpoint (<code>SET_ATTITUDE_TARGET.thrust</code>).</li><li>Body rate (<code>SET_ATTITUDE_TARGET</code> <code>.body_roll_rate</code> ,<code>.body_pitch_rate</code>, <code>.body_yaw_rate</code>) with thrust setpoint (<code>SET_ATTITUDE_TARGET.thrust</code>).</li></ul></li></ul></li></ul><h3 id="rover-1" tabindex="-1">Rover <a class="header-anchor" href="#rover-1" aria-label="Permalink to &quot;Rover&quot;">​</a></h3><p>Rover supports offboard control using the generic MAVLink position/velocity setpoint messages listed below. These are converted into a <a href="./../msg_docs/TrajectorySetpoint">TrajectorySetpoint</a> internally, and then into rover setpoints by the rover offboard modes. For rover-specific control setpoints and better behaviour we recommend using the <a href="#rover-setpoints">Rover Setpoints</a> via ROS 2.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Rover MAVLink setpoints are gated by the MAVLink parameter <a href="./../advanced_config/parameter_reference#MAV_FWDEXTSP">MAV_FWDEXTSP</a> (Forward external setpoint messages).</p></div><ul><li><p><a href="https://mavlink.io/en/messages/common.html#SET_POSITION_TARGET_LOCAL_NED" target="_blank" rel="noreferrer">SET_POSITION_TARGET_LOCAL_NED</a></p><ul><li>Position setpoint: <code>x</code>, <code>y</code> in <a href="https://mavlink.io/en/messages/common.html#MAV_FRAME_LOCAL_NED" target="_blank" rel="noreferrer">MAV_FRAME_LOCAL_NED</a> (<code>z</code> is ignored by rover modules).</li><li>Velocity setpoint: <code>vx</code>, <code>vy</code> in <a href="https://mavlink.io/en/messages/common.html#MAV_FRAME_LOCAL_NED" target="_blank" rel="noreferrer">MAV_FRAME_LOCAL_NED</a> or <a href="https://mavlink.io/en/messages/common.html#MAV_FRAME_BODY_NED" target="_blank" rel="noreferrer">MAV_FRAME_BODY_NED</a>.</li><li><code>yaw</code>/<code>yaw_rate</code>: <ul><li>Ackermann/Differential: ignored (in velocity control the yaw setpoint is derived from the velocity direction).</li><li>Mecanum: can be controlled independently (decoupled) using <code>yaw</code>/<code>yaw_rate</code>.</li></ul></li><li>Acceleration setpoints (<code>afx</code>, <code>afy</code>, <code>afz</code>) are ignored by rover modules.</li></ul></li><li><p><a href="https://mavlink.io/en/messages/common.html#SET_POSITION_TARGET_GLOBAL_INT" target="_blank" rel="noreferrer">SET_POSITION_TARGET_GLOBAL_INT</a></p><ul><li>Position setpoint: <code>lat_int</code>, <code>lon_int</code>, <code>alt</code> (converted into local NED internally; rover modules only use the horizontal components).</li><li>Velocity setpoint: <code>vx</code>, <code>vy</code>, <code>vz</code> (rover modules use only the horizontal components).</li><li>PX4 supports the following <code>coordinate_frame</code> values (only): <a href="https://mavlink.io/en/messages/common.html#MAV_FRAME_GLOBAL_INT" target="_blank" rel="noreferrer">MAV_FRAME_GLOBAL_INT</a>, <a href="https://mavlink.io/en/messages/common.html#MAV_FRAME_GLOBAL_RELATIVE_ALT_INT" target="_blank" rel="noreferrer">MAV_FRAME_GLOBAL_RELATIVE_ALT_INT</a>, <a href="https://mavlink.io/en/messages/common.html#MAV_FRAME_GLOBAL_TERRAIN_ALT_INT" target="_blank" rel="noreferrer">MAV_FRAME_GLOBAL_TERRAIN_ALT_INT</a>.</li></ul></li><li><p><a href="https://mavlink.io/en/messages/common.html#SET_ATTITUDE_TARGET" target="_blank" rel="noreferrer">SET_ATTITUDE_TARGET</a></p><ul><li>Not supported for rover offboard control.</li></ul></li></ul><h2 id="offboard-parameters" tabindex="-1">Offboard Parameters <a class="header-anchor" href="#offboard-parameters" aria-label="Permalink to &quot;Offboard Parameters&quot;">​</a></h2><p><em>Offboard mode</em> is affected by the following parameters:</p>`,81)),e("table",f,[t[7]||(t[7]=e("thead",null,[e("tr",null,[e("th",null,"Parameter"),e("th",null,"Опис")])],-1)),e("tbody",null,[t[4]||(t[4]=e("tr",null,[e("td",null,[e("a",{id:"COM_OF_LOSS_T"}),e("a",{href:"./../advanced_config/parameter_reference#COM_OF_LOSS_T"},"COM_OF_LOSS_T")]),e("td",null,[o("Time-out (in seconds) to wait when offboard connection is lost before triggering offboard lost failsafe ("),e("code",null,"COM_OBL_RC_ACT"),o(")")])],-1)),t[5]||(t[5]=e("tr",null,[e("td",null,[e("a",{id:"COM_OBL_RC_ACT"}),e("a",{href:"./../advanced_config/parameter_reference#COM_OBL_RC_ACT"},"COM_OBL_RC_ACT")]),e("td",null,"Flight mode to switch to if offboard control is lost.")],-1)),e("tr",null,[t[3]||(t[3]=e("td",null,[e("a",{id:"MAN_OVERRIDE_SPD"}),e("a",{href:"./../advanced_config/parameter_reference#MAN_OVERRIDE_SPD"},"MAN_OVERRIDE_SPD")],-1)),e("td",null,[t[0]||(t[0]=o("Speed (normalized stick travel per second) above which moving the sticks controlling a multicopter (or VTOL in hover) gives control back to the pilot by switching to ",-1)),t[1]||(t[1]=e("a",{href:"./../flight_modes_mc/position"},"Position mode",-1)),t[2]||(t[2]=o(" (or Altitude mode if position is unavailable). At the default value of 1 a half-stick movement in ~0.5 s triggers it; lower is more sensitive. A stick held statically has zero speed and will not trigger. Set to -1 to disable. ",-1)),h(i,{type:"tip",text:"PX4 v1.18"})])]),t[6]||(t[6]=e("tr",null,[e("td",null,[e("a",{id:"COM_RCL_EXCEPT"}),e("a",{href:"./../advanced_config/parameter_reference#COM_RCL_EXCEPT"},"COM_RCL_EXCEPT")]),e("td",null,[o("Specify modes in which RC loss is ignored and the failsafe action not triggered. Set bit "),e("code",null,"2"),o(" to ignore RC loss in Offboard mode.")])],-1))])]),t[9]||(t[9]=r('<h2 id="developer-resources" tabindex="-1">Developer Resources <a class="header-anchor" href="#developer-resources" aria-label="Permalink to &quot;Developer Resources&quot;">​</a></h2><p>Typically developers do not directly work at the MAVLink layer, but instead use a robotics API like <a href="https://mavsdk.mavlink.io/" target="_blank" rel="noreferrer">MAVSDK</a> or <a href="https://www.ros.org/" target="_blank" rel="noreferrer">ROS</a> (these provide a developer friendly API, and take care of managing and maintaining connections, sending messages and monitoring responses - the minutiae of working with <em>Offboard mode</em> and MAVLink).</p><p>The following resources may be useful for a developer audience:</p><ul><li><a href="./../ros/offboard_control">Offboard Control from Linux</a></li><li><a href="./../ros/mavros_offboard_cpp">ROS/MAVROS Offboard Example (C++)</a></li><li><a href="./../ros/mavros_offboard_python">ROS/MAVROS Offboard Example (Python)</a></li></ul>',4))])}const O=n(p,[["render",m]]);export{k as __pageData,O as default};
